module lfsr_nfsr_top(clk, rst, enable, plaintext, ciphertext, decrypted_text);
  wire [127:0] L;
  wire [127:0] L_next;
  wire [127:0] N;
  wire [127:0] N_next;
  wire [7:0] Z;
  output [7:0] ciphertext;
  wire [7:0] ciphertext;
  input clk;
  wire clk;
  output [7:0] decrypted_text;
  wire [7:0] decrypted_text;
  input enable;
  wire enable;
  input [7:0] plaintext;
  wire [7:0] plaintext;
  input rst;
  wire rst;
  DECRYPT dec_inst (
    .Z(Z),
    .ciphertext(ciphertext),
    .plaintext_out(decrypted_text)
  );
  ENCRYPT enc_inst (
    .Z(Z),
    .ciphertext(ciphertext),
    .plaintext(plaintext)
  );
  KEYSTREAM ks_inst (
    .L(L),
    .L_next(L_next),
    .N(N),
    .N_next(N_next),
    .Z(Z)
  );
  LFSR lfsr_inst (
    .L(L),
    .L_next(L_next),
    .clk(clk),
    .enable(enable),
    .rst(rst)
  );
  NFSR nfsr_inst (
    .N(N),
    .N_next(N_next),
    .clk(clk),
    .enable(enable),
    .rst(rst)
  );
endmodule
